CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS patients(id TEXT PRIMARY KEY,name TEXT NOT NULL,dob TEXT NOT NULL,phone TEXT NOT NULL,sex TEXT NOT NULL,administrative_note TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),doctor_id TEXT NOT NULL,date TEXT NOT NULL,time TEXT NOT NULL,duration INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS encounters(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),appointment_id TEXT REFERENCES appointments(id),summary TEXT NOT NULL,assessment TEXT NOT NULL,plan TEXT NOT NULL,author TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,role TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,record_id TEXT NOT NULL,role TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS appointment_calendar ON appointments(date,doctor_id,time);
CREATE INDEX IF NOT EXISTS encounter_patient ON encounters(patient_id,created_at);
